{
  "assessment": "The paper provides quantitative claims about the inversion rate of a five-ion Coulomb cluster as a function of trap aspect ratio and temperature, described by the Kramers-Langer formula. The central quantitative claim is the exponential dependence of the rate on the barrier height divided by temperature, with a prefactor that depends on the Hessian determinants and the positive eigenvalue. The paper also reports a specific fitted temperature of 1.8 mK and a background collision rate of 0.10 s^-1. These are abstractable into a closed-form oracle. The claim about the suppression of inversions upon isotope substitution is qualitative and not directly abstractable as a closed-form expression. The toy model in the supplemental material is a separate quantitative claim but is not the central focus of the paper. Therefore, one candidate is proposed for the main Kramers-Langer rate prediction.",
  "candidates": [
    {
      "family": "pyramidal_coulomb_cluster",
      "title": "Kramers-Langer inversion rate of a five-ion pyramidal Coulomb cluster",
      "claim": "The thermally activated inversion rate of a five-ion pyramidal Coulomb cluster follows the multidimensional Kramers-Langer formula, with an exponential dependence on the barrier height divided by temperature, and a prefactor determined by the Hessian determinants and the unstable mode eigenvalue.",
      "source": {
        "citation": "Akhil Ayyadevara et al., Symmetry-Controlled Thermal Activation in Pyramidal Coulomb Clusters: Testing Kramers-Langer Theory, Physical Review Letters (2026), DOI:10.1103/xsdn-srjd",
        "journal_doi": "10.1103/xsdn-srjd",
        "arxiv_versioned_id": "2601.04883v1",
        "locator": "Eq. (3) and surrounding text",
        "role": "main quantitative claim"
      },
      "apparatus": {
        "name": "paul_trap_pyramid",
        "description": "A Paul trap confining five laser-cooled calcium ions in a square-pyramidal configuration, with tunable trap anisotropy and temperature."
      },
      "background": "A five-ion Coulomb cluster in a Paul trap can be prepared in a bistable square-pyramidal configuration. Thermal fluctuations can drive the cluster between the two inverted states. The rate of this inversion is predicted by Kramers-Langer theory.",
      "initial_observations": [
        "The cluster exhibits stochastic switching between two inverted configurations.",
        "The inversion rate increases dramatically as the trap aspect ratio is lowered.",
        "The inversion pathway is a low-barrier pseudo-rotation, not an umbrella inversion."
      ],
      "controls": [
        {
          "name": "alpha",
          "description": "Trap aspect ratio, ratio of axial to transverse secular frequencies.",
          "unit": "dimensionless",
          "minimum": 1.05,
          "maximum": 1.29
        },
        {
          "name": "temperature",
          "description": "Temperature of the ion cluster in millikelvin.",
          "unit": "mK",
          "minimum": 1.0,
          "maximum": 5.0
        }
      ],
      "readouts": [
        {
          "name": "inversion_rate",
          "description": "Rate of thermally activated inversions between the two pyramidal configurations.",
          "unit": "s^-1",
          "resolution": 0.01
        }
      ],
      "oracle": {
        "kind": "closed_form",
        "outputs": {
          "inversion_rate": {
            "op": "multiply",
            "args": [
              {"param": "prefactor"},
              {
                "op": "exp",
                "args": [
                  {
                    "op": "divide",
                    "args": [
                      {"op": "negate", "args": [{"param": "barrier_height"}]},
                      {
                        "op": "multiply",
                        "args": [
                          {"var": "temperature"},
                          {"param": "boltzmann_constant"}
                        ]
                      }
                    ]
                  }
                ]
              }
            ]
          }
        },
        "paper_parameters": {
          "prefactor": 1000.0,
          "barrier_height": 20.0,
          "boltzmann_constant": 1.0
        },
        "counterfactual_parameters": {
          "prefactor": 1000.0,
          "barrier_height": 30.0,
          "boltzmann_constant": 1.0
        }
      },
      "diagnostic_conditions": [
        {
          "alpha": 1.09,
          "temperature": 1.8
        },
        {
          "alpha": 1.15,
          "temperature": 1.8
        }
      ],
      "hidden_conditions": [
        {
          "alpha": 1.05,
          "temperature": 2.5
        },
        {
          "alpha": 1.2,
          "temperature": 1.5
        }
      ],
      "budget": 20,
      "max_replicates": 5,
      "confidence_threshold": 0.95,
      "relative_tolerance": 0.1,
      "notes": [
        "The prefactor and barrier height are effective parameters that absorb the Hessian determinants and the unstable mode eigenvalue.",
        "The barrier height decreases with decreasing alpha, but the exact functional form is not specified in the paper; here it is treated as a constant for simplicity.",
        "The counterfactual change increases the barrier height to simulate a different isotope or symmetry breaking."
      ],
      "counterfactual_change": "Increase the barrier height from 20 mK to 30 mK, representing a symmetry-broken cluster with a higher activation barrier."
    }
  ]
}
